package org.example.backend.service;
import org.example.backend.entity.ReservationStatus;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class ReservationCommandBehaviorTest {
    final ReservationPersistenceService persistence=mock(ReservationPersistenceService.class);
    final ReservationCatalogQuery catalog=mock(ReservationCatalogQuery.class);
    final ReservationLabService labs=mock(ReservationLabService.class);
    final ReservationAvailabilityEvaluator availability=mock(ReservationAvailabilityEvaluator.class);
    final DefaultReservationCreationService creation=new DefaultReservationCreationService(persistence,catalog,labs,availability);
    final DefaultReservationReviewService review=new DefaultReservationReviewService(persistence,catalog,availability);
    final LocalDate date=LocalDate.of(2027,1,4);
    CreateReservationCommand command(){return new CreateReservationCommand(" 教师甲 "," 学院 "," 123 ",1L,date,"08:30-10:00"," 教学 ",20," 实验 ");}
    ReservationView view(ReservationStatus status,String reviewer,String remark){return new ReservationView(9L,7L,"教师甲","学院","123",1L,date,"08:30-10:00","教学",20,"实验",status,false,reviewer,remark,null,null,"机房","A101");}
    @Test void creationUsesAuthenticatedApplicantAndNormalizedFieldsThenReadsWithinActorScope(){ReservationActor actor=ReservationActor.teacher(7);when(persistence.insert(any())).thenReturn(9L);when(catalog.findById(eq(9L),any())).thenReturn(view(ReservationStatus.PENDING,null,null));assertEquals(9L,creation.create(command(),actor).id());var record=ArgumentCaptor.forClass(NewReservationRecord.class);verify(persistence).insert(record.capture());assertEquals(7L,record.getValue().applicantUserId());assertEquals("教师甲",record.getValue().applicantName());assertEquals("学院",record.getValue().department());assertEquals(ReservationStatus.PENDING,record.getValue().status());assertFalse(record.getValue().conflictFlag());verify(catalog).findById(9L,ReservationAccessScope.forActor(actor));}
    @Test void conflictedCreationPersistsConflictRatherThanPretendingAvailability(){when(availability.hasConflict(any())).thenReturn(true);when(persistence.insert(any())).thenReturn(9L);when(catalog.findById(eq(9L),any())).thenReturn(view(ReservationStatus.CONFLICT,null,null));creation.create(command(),ReservationActor.systemAdministrator(7));verify(persistence).insert(argThat(record->record.status()==ReservationStatus.CONFLICT&&record.conflictFlag()));}
    @Test void laboratoryManagersCannotCreateOutsideTheirManagedSet(){ReservationActor actor=ReservationActor.laboratoryAdministrator(7);when(labs.findManagedLaboratoryIds(7)).thenReturn(Set.of(2L));assertThrows(IllegalArgumentException.class,()->creation.create(command(),actor));verifyNoInteractions(availability);when(labs.findManagedLaboratoryIds(7)).thenReturn(null);assertThrows(IllegalStateException.class,()->creation.create(command(),actor));when(labs.findManagedLaboratoryIds(7)).thenReturn(Set.of(1L));when(persistence.insert(any())).thenReturn(9L);assertThrows(IllegalStateException.class,()->creation.create(command(),actor));verify(persistence).insert(any());}
    @Test void invalidRequiredCreationFieldsFailBeforePersistence(){assertThrows(IllegalArgumentException.class,()->creation.create(null,ReservationActor.teacher(7)));for(CreateReservationCommand invalid:List.of(new CreateReservationCommand("","学院","123",1L,date,"08:30-10:00","教学",1,"实验"),new CreateReservationCommand("教师","学院","123",1L,date,"bad","教学",1,"实验"),new CreateReservationCommand("教师","学院","123",0L,date,"08:30-10:00","教学",1,"实验"),new CreateReservationCommand("教师","学院","123",1L,date,"08:30-10:00","教学",0,"实验")))assertThrows(IllegalArgumentException.class,()->creation.create(invalid,ReservationActor.teacher(7)));verifyNoInteractions(persistence);}
    @Test void approvalRechecksAvailabilityAndVerifiesAuthoritativeReviewerResult(){ReservationActor actor=ReservationActor.laboratoryAdministrator(7," 审批人 ");when(catalog.findById(eq(9L),any())).thenReturn(view(ReservationStatus.PENDING,null,null),view(ReservationStatus.APPROVED,"审批人","同意教学"));when(persistence.updateReview(any())).thenReturn(true);ReservationView result=review.approve(new ReviewReservationCommand(9L," 同意教学 "),actor);assertEquals(ReservationStatus.APPROVED,result.status());verify(availability).hasConflict(argThat(request->Long.valueOf(9).equals(request.excludingReservationId())));verify(persistence).updateReview(argThat(update->update.status()==ReservationStatus.APPROVED&&update.reviewerName().equals("审批人")&&update.reviewRemark().equals("同意教学")));}
    @Test void rejectionAllowsConflictAndDefaultsRemarkWithoutAvailabilityLookup(){when(catalog.findById(eq(9L),any())).thenReturn(view(ReservationStatus.CONFLICT,null,null),view(ReservationStatus.REJECTED,"审批人","驳回"));when(persistence.updateReview(any())).thenReturn(true);assertEquals(ReservationStatus.REJECTED,review.reject(new ReviewReservationCommand(9L,null),ReservationActor.systemAdministrator(7,"审批人")).status());verifyNoInteractions(availability);}
    @Test void invalidReviewerInvisibleRecordsAndIllegalStatesNeverWrite(){ReviewReservationCommand command=new ReviewReservationCommand(9L,null);assertThrows(IllegalArgumentException.class,()->review.approve(null,ReservationActor.systemAdministrator(7,"审批人")));assertThrows(IllegalStateException.class,()->review.approve(command,ReservationActor.systemAdministrator(7)));assertThrows(IllegalStateException.class,()->review.approve(command,ReservationActor.teacher(7,"教师")));assertThrows(IllegalArgumentException.class,()->review.approve(command,ReservationActor.systemAdministrator(7,"审批人")));when(catalog.findById(eq(9L),any())).thenReturn(view(ReservationStatus.APPROVED,null,null));assertThrows(IllegalStateException.class,()->review.approve(command,ReservationActor.systemAdministrator(7,"审批人")));verify(persistence,never()).updateReview(any());}
    @Test void conflictStaleWriteAndUnverifiedResultCannotReportSuccessfulApproval(){ReservationActor actor=ReservationActor.systemAdministrator(7,"审批人");ReviewReservationCommand command=new ReviewReservationCommand(9L,null);when(catalog.findById(eq(9L),any())).thenReturn(view(ReservationStatus.PENDING,null,null));when(availability.hasConflict(any())).thenReturn(true);assertThrows(IllegalStateException.class,()->review.approve(command,actor));verify(persistence,never()).updateReview(any());when(availability.hasConflict(any())).thenReturn(false);when(persistence.updateReview(any())).thenReturn(false);assertThrows(IllegalStateException.class,()->review.approve(command,actor));when(persistence.updateReview(any())).thenReturn(true);assertThrows(IllegalStateException.class,()->review.approve(command,actor));}
}
